title: Cache Storage API Calls
impact: LOW-MEDIUM
impactDescription: reduces expensive I/O
tags: javascript, localStorage, storage, caching, performance
---

## Cache Storage API Calls

`localStorage`, `sessionStorage`, and `document.cookie` are synchronous and expensive. Cache reads in memory.

**Incorrect (reads storage on every call):**

```typescript
function getTheme() {
  return localStorage.getItem('theme') ?? 'light'
}
// Called 10 times = 10 storage reads
```

**Correct (Map cache):**

```typescript
const storageCache = new Map<string, string | null>()

function getLocalStorage(key: string) {
  if (!storageCache.has(key)) {
    storageCache.set(key, localStorage.getItem(key))
  }
  return storageCache.get(key)
}

function setLocalStorage(key: string, value: string) {
  localStorage.setItem(key, value)
  storageCache.set(key, value)  // keep cache in sync
}
```

Use a Map (not a hook) so it works everywhere: utilities, event handlers, not just React components.

**Cookie caching:**

```typescript
let cookieCache: Record<string, string> | null = null

function getCookie(name: string) {
  if (!cookieCache) {
    cookieCache = Object.fromEntries(
      document.cookie.split('; ').map(c => c.split('='))
    )
  }
  return cookieCache[name]
}
```

**Important (invalidate on external changes):**

If storage can change externally (another tab, server-set cookies), invalidate cache:

```typescript
window.addEventListener('storage', (e) => {
  if (e.key) storageCache.delete(e.key)
})

document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') {
    storageCache.clear()
  }
})
```

import {
  OrgEnrichedApiKey,
  createBasicAuthHeader,
  createOrgProjectAndApiKey,
  generateKeySet,
} from "@langfuse/shared/src/server";
import { Prisma, type PrismaClient, prisma } from "@langfuse/shared/src/db";
import { env } from "@/src/env.mjs";
import { ApiAuthService } from "@/src/features/public-api/server/apiAuth";
import { v4 } from "uuid";
import {
  clearRedisKeysByPatternSafely,
  createRedisTestClient,
  ensureRedisReady,
  getRedisKeysByPattern,
  getRedisTtl,
  getRedisValue,
  setRedisValue,
  type RedisTestClient,
} from "@/src/__tests__/server/redis-test-utils";

describe("Authenticate API calls", () => {
  type TestApiKeyFixture = {
    id: string;
    auth: string;
    publicKey: string;
    secretKey: string;
    orgId: string;
    projectId: string;
    note: string;
  };

  let testApiKey: TestApiKeyFixture;

  const createRedisClient = (): RedisTestClient => {
    return createRedisTestClient({
      maxRetriesPerRequest: null,
    });
  };

  const getValidAuthHeader = () => testApiKey.auth;

  const getInvalidAuthHeader = () =>
    createBasicAuthHeader(
      testApiKey.publicKey,
      `${testApiKey.secretKey}-wrong`,
    );

  const createMissingAuthHeader = () =>
    createBasicAuthHeader(`pk-missing-${v4()}`, `sk-missing-${v4()}`);

  const getApiKeyCacheKeys = async (
    redisClient: RedisTestClient,
    pattern = "api-key*",
  ) => {
    return await getRedisKeysByPattern(redisClient, pattern);
  };

  const clearApiKeyCacheSafely = async (redisClient: RedisTestClient) => {
    await clearRedisKeysByPatternSafely(redisClient, "api-key*");
  };

  beforeEach(async () => {
    const fixture = await createOrgProjectAndApiKey({ plan: "Hobby" });
    const note = "seeded key";
    const createdApiKey = await prisma.apiKey.findUniqueOrThrow({
      where: { publicKey: fixture.publicKey },
    });
    await prisma.apiKey.update({
      where: { id: createdApiKey.id },
      data: { note },
    });
    testApiKey = {
      id: createdApiKey.id,
      auth: fixture.auth,
      publicKey: fixture.publicKey,
      secretKey: fixture.secretKey,
      orgId: fixture.orgId,
      projectId: fixture.projectId,
      note,
    };
  });

  describe("validates without redis", () => {
    it("should create new api key", async () => {
      const auth = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());

      expect(auth.validKey).toBe(true);

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();
    });

    it("should create new api key and succeed with new key", async () => {
      const auth = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());
      expect(auth.validKey).toBe(true);

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      const auth2 = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());
      expect(auth2.validKey).toBe(true);
    });

    it("should create new api key with stripe data and succeed with new key", async () => {
      await prisma.organization.update({
        where: {
          id: testApiKey.orgId,
        },
        data: {
          cloudConfig: {
            stripe: {
              customerId: "cus_test123",
              activeSubscriptionId: "sub_test123",
              activeProductId: "prod_test123",
            },
          },
        },
      });

      await new ApiAuthService(prisma, null).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      const auth = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());
      expect(auth.validKey).toBe(true);

      if (auth.validKey) {
        expect(auth.scope.orgId).toBe(testApiKey.orgId);
        expect(auth.scope.plan).toBe("cloud:hobby");
        expect(auth.scope.rateLimitOverrides).toEqual([]);
      }

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      await prisma.organization.update({
        where: {
          id: testApiKey.orgId,
        },
        data: {
          cloudConfig: Prisma.JsonNull,
        },
      });
    });

    it("should create new api key with custom rate limits and succeed with new key", async () => {
      await prisma.organization.update({
        where: {
          id: testApiKey.orgId,
        },
        data: {
          cloudConfig: {
            rateLimitOverrides: [
              {
                resource: "ingestion",
                points: 100,
                durationInSec: 60,
              },
            ],
          },
        },
      });

      await new ApiAuthService(prisma, null).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      const auth = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());
      expect(auth.validKey).toBe(true);

      if (auth.validKey) {
        expect(auth.scope.orgId).toBe(testApiKey.orgId);
        expect(auth.scope.plan).toBe("cloud:hobby");
        expect(auth.scope.rateLimitOverrides).toEqual([
          {
            resource: "ingestion",
            points: 100,
            durationInSec: 60,
          },
        ]);
      }

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      await prisma.organization.update({
        where: {
          id: testApiKey.orgId,
        },
        data: {
          cloudConfig: Prisma.JsonNull,
        },
      });
    });

    it("should fail on wrong api key with new key", async () => {
      const auth = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());
      expect(auth.validKey).toBe(true);

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });

      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      const wrongAuth = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getInvalidAuthHeader());
      expect(wrongAuth.validKey).toBe(false);
    });

    it("should fail on wrong api key without new key", async () => {
      const initialApiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(initialApiKey).not.toBeNull();
      expect(initialApiKey?.fastHashedSecretKey).toBeNull();

      const auth = await new ApiAuthService(
        prisma,
        null,
      ).verifyAuthHeaderAndReturnScope(getInvalidAuthHeader());
      expect(auth.validKey).toBe(false);

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).toBeNull();
    });
  });

  describe("validates with redis", () => {
    let redis: RedisTestClient;

    beforeAll(async () => {
      redis = createRedisClient();
      await ensureRedisReady(redis);
    }, 20_000);

    beforeEach(async () => {
      if (redis.status === "close" || redis.status === "end") {
        redis = createRedisClient();
      }
      await ensureRedisReady(redis);
      // if we do not remove the key, it will remain in the cache and
      // calling the test twice will not add the key to the cache
      await clearApiKeyCacheSafely(redis);
    }, 20_000);

    afterEach(async () => {
      // if we do not remove the key, it will remain in the cache and
      // calling the test twice will not add the key to the cache
      await clearApiKeyCacheSafely(redis);
    }, 20_000);

    afterAll(() => {
      redis.disconnect();
    }, 20_000);

    it("should create new api key and read from cache", async () => {
      // update the organization with a cloud config
      await prisma.organization.update({
        where: { id: testApiKey.orgId },
        data: {
          cloudConfig: {
            rateLimitOverrides: [
              {
                resource: "public-api",
                points: 1000,
                durationInSec: 60,
              },
              {
                resource: "ingestion",
              },
            ],
          },
        },
      });

      // first auth will generate the fast hashed api key
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });

      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      const cachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(cachedKey).toBeNull();

      // second will add the key to redis
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      const cachedKey2 = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );

      expect(cachedKey2).not.toBeNull();

      const parsed = OrgEnrichedApiKey.parse(JSON.parse(cachedKey2!));

      expect(parsed).toEqual({
        ...apiKey,
        orgId: testApiKey.orgId,
        plan: "cloud:hobby",
        rateLimitOverrides: [
          {
            resource: "public-api",
            points: 1000,
            durationInSec: 60,
          },
          {
            resource: "ingestion",
          },
        ],
        createdAt: apiKey?.createdAt.toISOString(),
        isIngestionSuspended: expect.anything(),
      });

      await prisma.organization.update({
        where: { id: testApiKey.orgId },
        data: {
          cloudConfig: Prisma.JsonNull,
        },
      });
    });

    it("should handle non-scoped key format gracefully and fallback to prisma", async () => {
      // update the organization with a cloud config
      await prisma.organization.update({
        where: { id: testApiKey.orgId },
        data: {
          cloudConfig: {
            rateLimitOverrides: [
              {
                resource: "public-api",
                points: 1000,
                durationInSec: 60,
              },
              {
                resource: "ingestion",
              },
            ],
          },
        },
      });

      // first auth will generate the fast hashed api key
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });

      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      // Manually add a non-scoped key to Redis (missing the scope property)
      const nonScopedKey = {
        id: "seed-api-key",
        note: "seeded key",
        publicKey: testApiKey.publicKey,
        displaySecretKey: "sk-lf-...7890",
        createdAt: new Date().toISOString(),
        lastUsedAt: null,
        expiresAt: null,
        fastHashedSecretKey: apiKey?.fastHashedSecretKey,
        hashedSecretKey: apiKey?.hashedSecretKey,
        orgId: testApiKey.orgId,
        plan: "cloud:team",
        projectId: testApiKey.projectId,
        // scope property is intentionally missing
      };

      // Add the non-scoped key to Redis
      await setRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
        JSON.stringify(nonScopedKey),
      );

      // Verify the key is in Redis
      const cachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(cachedKey).not.toBeNull();

      // Parse should fail because the scope is missing
      expect(() => {
        OrgEnrichedApiKey.parse(JSON.parse(cachedKey!));
      }).toThrow("invalid_union");

      // Auth should still succeed by falling back to Postgres
      const verification = await new ApiAuthService(
        prisma,
        redis,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());

      expect(verification.validKey).toBe(true);

      // The invalid key should be removed from Redis
      const cachedKeyAfterAuth = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );

      // A new valid key should be added to Redis after fallback to Postgres
      expect(cachedKeyAfterAuth).not.toBeNull();

      // The new key should be properly formatted with a scope
      const parsed = OrgEnrichedApiKey.parse(JSON.parse(cachedKeyAfterAuth!));

      expect(parsed).toEqual({
        ...apiKey,
        orgId: testApiKey.orgId,
        plan: "cloud:hobby",
        scope: "PROJECT", // Now the scope is present
        projectId: testApiKey.projectId,
        rateLimitOverrides: [
          {
            resource: "public-api",
            points: 1000,
            durationInSec: 60,
          },
          {
            resource: "ingestion",
          },
        ],
        createdAt: apiKey?.createdAt.toISOString(),
        isIngestionSuspended: expect.anything(),
      });

      await prisma.organization.update({
        where: { id: testApiKey.orgId },
        data: {
          cloudConfig: Prisma.JsonNull,
        },
      });
    });

    it("searching for non-existing key stores flag in redis and fails auth", async () => {
      // key does not exist in database
      const missingAuthHeader = createMissingAuthHeader();

      const verification = await new ApiAuthService(
        prisma,
        redis,
      ).verifyAuthHeaderAndReturnScope(missingAuthHeader);

      expect(verification.validKey).toBe(false);

      const redisKeys = await getApiKeyCacheKeys(redis, "api-key:*");
      expect(redisKeys.length).toBe(1);
      const redisValue = await getRedisValue(redis, redisKeys[0]);
      expect(redisValue).toBe('"api-key-non-existent"');
    });

    it("searching for non-existing key again fails auth", async () => {
      // key does not exist in database
      const missingAuthHeader = createMissingAuthHeader();

      const verification = await new ApiAuthService(
        prisma,
        redis,
      ).verifyAuthHeaderAndReturnScope(missingAuthHeader);

      expect(verification.validKey).toBe(false);

      const redisKeys = await getApiKeyCacheKeys(redis, "api-key:*");
      expect(redisKeys.length).toBe(1);
      const redisValue = await getRedisValue(redis, redisKeys[0]);
      expect(redisValue).toBe('"api-key-non-existent"');

      const verification2 = await new ApiAuthService(
        prisma,
        redis,
      ).verifyAuthHeaderAndReturnScope(missingAuthHeader);
      expect(verification2.validKey).toBe(false);

      const redisKeys2 = await getApiKeyCacheKeys(redis, "api-key:*");
      expect(redisKeys2.length).toBe(1);
      const redisValue2 = await getRedisValue(redis, redisKeys[0]);
      expect(redisValue2).toBe('"api-key-non-existent"');
    });

    it("prisma should not be used when reading cached keys", async () => {
      // Mock prisma
      const mockPrisma = {
        apiKey: {
          findUnique: jest.fn(),
        },
      };

      // first auth will generate the fast hashed api key
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      // second will add the key to redis
      const auth2 = await new ApiAuthService(
        prisma,
        redis,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());

      // third will read from redis only
      await new ApiAuthService(
        mockPrisma as unknown as PrismaClient,
        redis,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());

      expect(auth2.validKey).toBe(true);

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      // Ensure prisma was not called
      expect(mockPrisma.apiKey.findUnique).not.toHaveBeenCalled();

      const cachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(cachedKey).not.toBeNull();

      const parsed = OrgEnrichedApiKey.parse(JSON.parse(cachedKey!));

      expect(parsed).toEqual({
        id: expect.any(String),
        note: "seeded key",
        publicKey: testApiKey.publicKey,
        hashedSecretKey: expect.any(String),
        fastHashedSecretKey: expect.any(String),
        displaySecretKey: expect.any(String),
        createdAt: expect.any(String),
        lastUsedAt: null,
        expiresAt: null,
        isIngestionSuspended: expect.anything(),
        projectId: expect.any(String),
        orgId: testApiKey.orgId,
        plan: "cloud:hobby",
        scope: "PROJECT",
      });
    });

    it("ttl should be increased when reading from redis", async () => {
      // Mock prisma
      const mockPrisma = {
        apiKey: {
          findUnique: jest.fn(),
        },
      };

      // first auth will generate the fast hashed api key
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      // second will add the key to redis
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      // third will read from redis only
      await new ApiAuthService(
        mockPrisma as unknown as PrismaClient,
        redis,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      const ttl = await getRedisTtl(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );

      expect(ttl).toBeGreaterThan(env.LANGFUSE_CACHE_API_KEY_TTL_SECONDS - 2);

      // wait for 5 seconds
      await new Promise((resolve) => setTimeout(resolve, 5000));

      await new ApiAuthService(
        mockPrisma as unknown as PrismaClient,
        redis,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());

      const ttl2 = await getRedisTtl(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );

      expect(ttl2).toBeGreaterThan(env.LANGFUSE_CACHE_API_KEY_TTL_SECONDS - 2);
    }, 10000);

    it("should delete API keys from cache and db", async () => {
      // first auth will generate the fast hashed api key
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      // second will add the key to redis
      const auth2 = await new ApiAuthService(
        prisma,
        redis,
      ).verifyAuthHeaderAndReturnScope(getValidAuthHeader());

      expect(auth2.validKey).toBe(true);

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });

      expect(apiKey).not.toBeNull();
      expect(apiKey?.fastHashedSecretKey).not.toBeNull();

      const cachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(cachedKey).not.toBeNull();

      const parsed = OrgEnrichedApiKey.parse(JSON.parse(cachedKey!));

      expect(parsed).toEqual({
        ...apiKey,
        orgId: testApiKey.orgId,
        plan: "cloud:hobby",
        createdAt: apiKey?.createdAt.toISOString(),
        scope: "PROJECT",
        isIngestionSuspended: expect.anything(),
      });

      await new ApiAuthService(prisma, redis).deleteApiKey(
        apiKey?.id!,
        apiKey?.projectId!,
        "PROJECT",
      );

      const deletedApiKey = await prisma.apiKey.findUnique({
        where: { id: apiKey?.id! },
      });
      expect(deletedApiKey).toBeNull();

      const deletedCachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(deletedCachedKey).toBeNull();
    });
  });

  describe("invalidates api keys in redis", () => {
    let redis: RedisTestClient;

    beforeAll(async () => {
      redis = createRedisClient();
      await ensureRedisReady(redis);
    }, 20_000);

    beforeEach(async () => {
      if (redis.status === "close" || redis.status === "end") {
        redis = createRedisClient();
      }
      await ensureRedisReady(redis);
      // if we do not remove the key, it will remain in the cache and
      // calling the test twice will not add the key to the cache
      await clearApiKeyCacheSafely(redis);
    }, 20_000);

    afterEach(async () => {
      // if we do not remove the key, it will remain in the cache and
      // calling the test twice will not add the key to the cache
      await clearApiKeyCacheSafely(redis);
    }, 20_000);

    afterAll(() => {
      redis.disconnect();
    }, 20_000);

    it("should invalidate organization API keys in redis", async () => {
      // put keys into cache
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();

      const cachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(cachedKey).not.toBeNull();

      await new ApiAuthService(prisma, redis).invalidateCachedOrgApiKeys(
        testApiKey.orgId,
      );

      const invalidatedCachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(invalidatedCachedKey).toBeNull();
    });

    it("if no keys in redis, invalidating org keys should do nothing", async () => {
      await prisma.apiKey.update({
        where: { publicKey: testApiKey.publicKey },
        data: {
          fastHashedSecretKey: Math.random().toString(36).substring(2, 15),
        },
      });

      await new ApiAuthService(prisma, redis).invalidateCachedOrgApiKeys(
        testApiKey.orgId,
      );

      const keys = await getApiKeyCacheKeys(redis);
      expect(keys.length).toBe(0);
    });

    it("if no keys in redis, invalidating org keys without fast hash should do nothing", async () => {
      await new ApiAuthService(prisma, redis).invalidateCachedOrgApiKeys(
        testApiKey.orgId,
      );

      const keys = await getApiKeyCacheKeys(redis);
      expect(keys.length).toBe(0);
    });

    it("should invalidate project API keys in redis", async () => {
      // put keys into cache
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );
      await new ApiAuthService(prisma, redis).verifyAuthHeaderAndReturnScope(
        getValidAuthHeader(),
      );

      const apiKey = await prisma.apiKey.findUnique({
        where: { publicKey: testApiKey.publicKey },
      });
      expect(apiKey).not.toBeNull();

      const cachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(cachedKey).not.toBeNull();

      await new ApiAuthService(prisma, redis).invalidateCachedProjectApiKeys(
        testApiKey.projectId,
      );

      const invalidatedCachedKey = await getRedisValue(
        redis,
        `api-key:${apiKey?.fastHashedSecretKey}`,
      );
      expect(invalidatedCachedKey).toBeNull();
    });

    it("if no keys in redis, invalidating project keys should do nothing", async () => {
      await prisma.apiKey.update({
        where: { publicKey: testApiKey.publicKey },
        data: {
          fastHashedSecretKey: Math.random().toString(36).substring(2, 15),
        },
      });

      await new ApiAuthService(prisma, redis).invalidateCachedProjectApiKeys(
        testApiKey.projectId,
      );

      const keys = await getApiKeyCacheKeys(redis);
      expect(keys.length).toBe(0);
    });

    it("if no keys in redis, invalidating project keys without fast hash should do nothing", async () => {
      await prisma.apiKey.update({
        where: { publicKey: testApiKey.publicKey },
        data: {
          fastHashedSecretKey: Math.random().toString(36).substring(2, 15),
        },
      });

      await new ApiAuthService(prisma, redis).invalidateCachedProjectApiKeys(
        testApiKey.projectId,
      );

      const keys = await getApiKeyCacheKeys(redis);
      expect(keys.length).toBe(0);
    });
  });

  describe("API key format", () => {
    it("generated public and secret keys never contain a colon (30 iterations)", async () => {
      // Keys are built as `pk-lf-<uuid>` / `sk-lf-<uuid>`.
      // UUIDs only use hex digits (0-9, a-f) and hyphens, so colons are
      // structurally impossible – but we assert it explicitly so any future
      // change to the generation logic gets caught before it can break
      // Basic-Auth header parsing (which splits on ':').
      for (let i = 0; i < 30; i++) {
        const { pk, sk } = await generateKeySet();
        expect(pk).not.toContain(":");
        expect(sk).not.toContain(":");
      }
    });
  });
});

import { type NextApiRequest } from "next";
import { verifyAuth } from "@/src/features/public-api/server/createAuthedProjectAPIRoute";
import { prisma } from "@langfuse/shared/src/db";
import { env } from "@/src/env.mjs";
import {
  createOrgProjectAndApiKey,
  hashSecretKey,
  getDisplaySecretKey,
} from "@langfuse/shared/src/server";

describe("Admin API Key Authentication", () => {
  const ADMIN_API_KEY = "test-admin-key-123";

  // Store original env value to restore after tests
  const originalAdminApiKey = env.ADMIN_API_KEY;
  const originalCloudRegion = env.NEXT_PUBLIC_LANGFUSE_CLOUD_REGION;

  let projectId: string;
  let orgId: string;
  let auth: string;

  beforeAll(() => {
    // Set up env for admin API key tests
    (env as any).ADMIN_API_KEY = ADMIN_API_KEY;
    (env as any).NEXT_PUBLIC_LANGFUSE_CLOUD_REGION = undefined;
  });

  afterAll(() => {
    // Restore original env values
    (env as any).ADMIN_API_KEY = originalAdminApiKey;
    (env as any).NEXT_PUBLIC_LANGFUSE_CLOUD_REGION = originalCloudRegion;
  });

  beforeEach(async () => {
    // Create a new project and API key for each test
    const result = await createOrgProjectAndApiKey();
    projectId = result.projectId;
    orgId = result.orgId;
    auth = result.auth;
  });

  describe("Basic Auth (isAdminApiKeyAuthAllowed = false)", () => {
    it("should successfully authenticate with valid basic auth", async () => {
      // auth from beforeEach contains a valid API key
      const mockReq = {
        headers: {
          authorization: auth,
        },
      } as NextApiRequest;

      const result = await verifyAuth(mockReq, false);

      expect(result.validKey).toBe(true);
      expect(result.scope.projectId).toBe(projectId);
      expect(result.scope.accessLevel).toBe("project");
    });

    it("should throw error when basic auth fails", async () => {
      const mockReq = {
        headers: {
          authorization: "Basic invalid",
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, false)).rejects.toEqual({
        status: 401,
        message: expect.stringContaining(""),
      });
    });

    it("should throw error when projectId is missing", async () => {
      // Create an org-level key (generate unique values to avoid conflicts)
      const timestamp = Date.now();
      const uniqueId = `org-api-key-${timestamp}`;
      const publicKey = `pk-org-key-${timestamp}`;
      const secretKey = `sk-org-key-${timestamp}`;

      await prisma.apiKey.create({
        data: {
          id: uniqueId,
          publicKey,
          hashedSecretKey: await hashSecretKey(secretKey),
          displaySecretKey: getDisplaySecretKey(secretKey),
          note: "org key",
          organization: {
            connect: { id: orgId },
          },
        },
      });

      const mockReq = {
        headers: {
          authorization:
            "Basic " +
            Buffer.from(`${publicKey}:${secretKey}`).toString("base64"),
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, false)).rejects.toMatchObject({
        status: 401,
        message: expect.stringContaining(""),
      });
    });
  });

  describe("Admin API Key Auth (isAdminApiKeyAuthAllowed = true)", () => {
    it("should successfully authenticate with valid admin API key", async () => {
      const mockReq = {
        headers: {
          authorization: `Bearer ${ADMIN_API_KEY}`,
          "x-langfuse-admin-api-key": ADMIN_API_KEY,
          "x-langfuse-project-id": projectId,
        },
      } as NextApiRequest;

      const result = await verifyAuth(mockReq, true);

      expect(result.validKey).toBe(true);
      expect(result.scope.projectId).toBe(projectId);
      expect(result.scope.orgId).toBe(orgId);
      expect(result.scope.apiKeyId).toBe("ADMIN_API_KEY");
      expect(result.scope.publicKey).toBe("ADMIN_API_KEY");
      expect(result.scope.accessLevel).toBe("project");
    });

    it("should fall back to basic auth when no Bearer header", async () => {
      const mockReq = {
        headers: {
          authorization: auth,
        },
      } as NextApiRequest;

      const result = await verifyAuth(mockReq, true);

      expect(result.validKey).toBe(true);
      expect(result.scope.projectId).toBe(projectId);
      expect(result.scope.apiKeyId).not.toBe("ADMIN_API_KEY");
    });

    it("should fall back to basic auth when no x-langfuse-admin-api-key header", async () => {
      const mockReq = {
        headers: {
          authorization: auth,
        },
      } as NextApiRequest;

      const result = await verifyAuth(mockReq, true);

      expect(result.validKey).toBe(true);
      expect(result.scope.projectId).toBe(projectId);
    });

    it("should fail on Langfuse Cloud", async () => {
      (env as any).NEXT_PUBLIC_LANGFUSE_CLOUD_REGION = "prod-us";

      const mockReq = {
        headers: {
          authorization: `Bearer ${ADMIN_API_KEY}`,
          "x-langfuse-admin-api-key": ADMIN_API_KEY,
          "x-langfuse-project-id": projectId,
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, true)).rejects.toEqual({
        status: 403,
        message: "Admin API key auth is not available on Langfuse Cloud",
      });

      (env as any).NEXT_PUBLIC_LANGFUSE_CLOUD_REGION = undefined;
    });

    it("should fail when ADMIN_API_KEY is not configured", async () => {
      (env as any).ADMIN_API_KEY = undefined;

      const mockReq = {
        headers: {
          authorization: "Bearer some-key",
          "x-langfuse-admin-api-key": "some-key",
          "x-langfuse-project-id": projectId,
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, true)).rejects.toEqual({
        status: 500,
        message: "Admin API key is not configured on this instance",
      });

      (env as any).ADMIN_API_KEY = ADMIN_API_KEY;
    });

    it("should fail with invalid Bearer token", async () => {
      const mockReq = {
        headers: {
          authorization: "Bearer wrong-key",
          "x-langfuse-admin-api-key": ADMIN_API_KEY,
          "x-langfuse-project-id": projectId,
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, true)).rejects.toEqual({
        status: 401,
        message: "Invalid admin API key",
      });
    });

    it("should fail with invalid x-langfuse-admin-api-key header", async () => {
      const mockReq = {
        headers: {
          authorization: `Bearer ${ADMIN_API_KEY}`,
          "x-langfuse-admin-api-key": "wrong-key",
          "x-langfuse-project-id": projectId,
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, true)).rejects.toEqual({
        status: 401,
        message: "Invalid admin API key",
      });
    });

    it("should fail when both admin key headers don't match ADMIN_API_KEY", async () => {
      const mockReq = {
        headers: {
          authorization: "Bearer different-key-1",
          "x-langfuse-admin-api-key": "different-key-2",
          "x-langfuse-project-id": projectId,
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, true)).rejects.toEqual({
        status: 401,
        message: "Invalid admin API key",
      });
    });

    it("should fail without x-langfuse-project-id header", async () => {
      const mockReq = {
        headers: {
          authorization: `Bearer ${ADMIN_API_KEY}`,
          "x-langfuse-admin-api-key": ADMIN_API_KEY,
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, true)).rejects.toEqual({
        status: 400,
        message:
          "x-langfuse-project-id header is required for admin API key authentication",
      });
    });

    it("should fail with non-existent project", async () => {
      const mockReq = {
        headers: {
          authorization: `Bearer ${ADMIN_API_KEY}`,
          "x-langfuse-admin-api-key": ADMIN_API_KEY,
          "x-langfuse-project-id": "non-existent-project",
        },
      } as NextApiRequest;

      await expect(verifyAuth(mockReq, true)).rejects.toEqual({
        status: 404,
        message: "Project not found",
      });
    });

    it("should fall back to basic auth successfully after admin auth not attempted", async () => {
      const mockReq = {
        headers: {
          authorization: auth,
          "x-langfuse-project-id": projectId,
        },
      } as NextApiRequest;

      const result = await verifyAuth(mockReq, true);

      expect(result.validKey).toBe(true);
      expect(result.scope.projectId).toBe(projectId);
      expect(result.scope.apiKeyId).not.toBe("ADMIN_API_KEY");
    });
  });
});

